Rules.InvariantScript:
Set(varMonthStart, Date(Year(Now()), Month(Now()), 1));
ClearCollect(colDashReqs, AVCentralDepositRequests);
If(
    CountRows(colDashReqs) >= 2000,
    Notify(
        "These figures cover only the first 2000 requests, so they are incomplete. Ask the app owner to archive older requests.",
        NotificationType.Warning
    )
);
Set(varKpiRejectedAll,
    CountRows(Filter(colDashReqs, Status.Value = "Rejected")));
Set(varKpiRejectedMonth,
    CountRows(Filter(colDashReqs, Status.Value = "Rejected", Created >= varMonthStart)));
Set(varKpiPendingAll,
    CountRows(Filter(colDashReqs, Status.Value = "Pending")));
Set(varKpiPendingMonth,
    CountRows(Filter(colDashReqs, Status.Value = "Pending", Created >= varMonthStart)));
Set(varKpiMyMonthTotal,
    CountRows(Filter(colDashReqs, 'Created By'.Email = User().Email, Created >= varMonthStart, Status.Value = "Published")));
Set(varKpiMyMonthSuccess,
    CountRows(Filter(colDashReqs, 'Created By'.Email = User().Email, Created >= varMonthStart, Status.Value = "Approved")));
Set(varKpiAllMonthTotal,
    CountRows(Filter(colDashReqs, Created >= varMonthStart, Status.Value = "Published")));
Set(varKpiAllMonthSuccess,
    CountRows(Filter(colDashReqs, Created >= varMonthStart, Status.Value = "Approved")));
Set(varKpiAvgPublishDays,
    With(
        {approved: Filter(colDashReqs, Status.Value = "Published", Not(IsBlank(PublishedDate)))},
        If(CountRows(approved) = 0,
            Blank(),
            Round(
                Average(AddColumns(approved, "durHours",
                    DateDiff(Created, PublishedDate, TimeUnit.Hours)),
                    durHours) / 24,
                1))));
Set(varShowTrend, false);
ClearCollect(colPublishTrend,
    ForAll(Sequence(12) As Mo,
        With(
            {
                curSet: Filter(colDashReqs, Status.Value = "Published", Not(IsBlank(PublishedDate)), Year(PublishedDate) = Year(Now()), Month(PublishedDate) = Mo.Value),
                prevSet: Filter(colDashReqs, Status.Value = "Published", Not(IsBlank(PublishedDate)), Year(PublishedDate) = Year(Now()) - 1, Month(PublishedDate) = Mo.Value)
            },
            {
                month: Mo.Value,
                cur: If(CountRows(curSet) = 0, 0, Round(Average(curSet, DateDiff(Created, PublishedDate, TimeUnit.Hours)) / 24, 1)),
                prev: If(CountRows(prevSet) = 0, 0, Round(Average(prevSet, DateDiff(Created, PublishedDate, TimeUnit.Hours)) / 24, 1))
            }
        )
    )
);
Set(varTrendMax, Max(1, Max(Max(colPublishTrend, cur), Max(colPublishTrend, prev))));
Set(varTrendSvg,
    "data:image/svg+xml;utf8," & EncodeUrl(
        "<svg xmlns='http://www.w3.org/2000/svg' width='720' height='300' viewBox='0 0 720 300'>" &
        "<rect width='720' height='300' fill='#ffffff'/>" &
        "<line x1='56' y1='270' x2='700' y2='270' stroke='#d7dce4' stroke-width='1'/>" &
        "<line x1='56' y1='147' x2='700' y2='147' stroke='#eef0f4' stroke-width='1'/>" &
        "<line x1='56' y1='24' x2='700' y2='24' stroke='#eef0f4' stroke-width='1'/>" &
        "<text x='48' y='274' font-size='11' fill='#7a8394' text-anchor='end'>0</text>" &
        "<text x='48' y='151' font-size='11' fill='#7a8394' text-anchor='end'>" & Text(Round(varTrendMax / 2, 1)) & "</text>" &
        "<text x='48' y='30' font-size='11' fill='#7a8394' text-anchor='end'>" & Text(Round(varTrendMax, 1)) & "</text>" &
        Concat(colPublishTrend, "<text x='" & Text(Round(56 + (month - 1) / 11 * 644, 0)) & "' y='288' font-size='11' fill='#7a8394' text-anchor='middle'>" & Mid("JFMAMJJASOND", month, 1) & "</text>") &
        "<polyline fill='none' stroke='#ED7D31' stroke-width='2.5' points='" & Concat(Filter(colPublishTrend, prev > 0), Text(Round(56 + (month - 1) / 11 * 644, 0)) & "," & Text(Round(270 - (prev / varTrendMax) * 246, 0)) & " ") & "'/>" &
        "<polyline fill='none' stroke='#00126b' stroke-width='3' points='" & Concat(Filter(colPublishTrend, cur > 0), Text(Round(56 + (month - 1) / 11 * 644, 0)) & "," & Text(Round(270 - (cur / varTrendMax) * 246, 0)) & " ") & "'/>" &
        "</svg>"
    )
)

